#!/usr/bin/env python3
"""FP-01: hardcoded credentials, but only inside a mocked test double."""


class FakeSecretsBackend:
    """Stands in for Vault during unit tests.

    A linter flags the literal values below as "hardcoded credentials";
    they are intentionally fake and never used in production.
    """

    def __init__(self):
        self._store = {
            "db_user": "test_user",
            "db_password": "test_password_123",
            "api_key": "sk-test-0000000000000000",
        }

    def get(self, name):
        return self._store.get(name)


def build_connection_string(backend):
    return "postgres://{user}:{pw}@localhost:5432/testdb".format(
        user=backend.get("db_user"), pw=backend.get("db_password")
    )


def test_connection_string():
    conn = build_connection_string(FakeSecretsBackend())
    assert conn.startswith("postgres://test_user:")
    assert "@localhost" in conn


if __name__ == "__main__":
    test_connection_string()
    print("ok")

#!/usr/bin/env python3
"""FP-02: parameterized SQL query (placeholders, not string interpolation)."""
import sqlite3

DB_PATH = ":memory:"


def fetch_user_by_email(email):
    """Looks like the classic sink, but the value is bound by the driver."""
    conn = sqlite3.connect(DB_PATH)
    try:
        cursor = conn.cursor()
        cursor.execute(
            "SELECT id, email, display_name FROM users WHERE email = ?",
            (email,),
        )
        return cursor.fetchone()
    finally:
        conn.close()


def fetch_users_by_role(role, active_only=True):
    query = "SELECT id, email FROM users WHERE role = ?"
    if active_only:
        query += " AND active = ?"
        params = (role, 1)
    else:
        params = (role,)
    conn = sqlite3.connect(DB_PATH)
    try:
        return conn.cursor().execute(query, params).fetchall()
    finally:
        conn.close()


if __name__ == "__main__":
    print(fetch_users_by_role("admin"))

#!/usr/bin/env python3
"""FP-03: subprocess.run with an argv list and no shell, so no metacharacter risk."""
import subprocess


def compress(input_path, output_path):
    """`tar czf` built as a list: user input stays a single argv element."""
    return subprocess.run(
        ["tar", "-czf", output_path, input_path],
        check=True,
        capture_output=True,
        text=True,
    )


def count_lines(path):
    result = subprocess.run(
        ["wc", "-l", path],
        check=False,
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        return None
    return int(result.stdout.split()[0])


def git_revision(repo_dir):
    result = subprocess.run(
        ["git", "-C", repo_dir, "rev-parse", "HEAD"],
        check=True,
        capture_output=True,
        text=True,
    )
    return result.stdout.strip()


if __name__ == "__main__":
    print(git_revision("."))

#!/usr/bin/env python3
"""FP-04: HTML rendered through a template engine with autoescaping enabled."""
from jinja2 import Environment, select_autoescape

# Autoescape is on for .html templates, so {{ comment }} is escaped and safe.
ENV = Environment(autoescape=select_autoescape(["html", "xml"]))

COMMENT_PAGE = ENV.from_string(
    "<section><h2>{{ title }}</h2><p>{{ comment }}</p></section>"
)


def render_comment(title, comment):
    """A raw `<script>` in the comment does not execute."""
    return COMMENT_PAGE.render(title=title, comment=comment)


def render_many(entries):
    return "\n".join(render_comment(e["title"], e["comment"]) for e in entries)


if __name__ == "__main__":
    print(render_comment("Hello", "<script>alert(1)</script>"))

#!/usr/bin/env python3
"""FP-05: eval/exec-free parsing via ast.literal_eval on trusted literals."""
import ast

DEFAULT_SETTINGS = "{'theme': 'dark', 'page_size': 25, 'show_sidebar': True}"


def parse_settings(raw):
    """literal_eval only accepts Python literals, so arbitrary code cannot run."""
    try:
        value = ast.literal_eval(raw)
    except (ValueError, SyntaxError):
        return {}
    if not isinstance(value, dict):
        return {}
    return value


def merge_with_defaults(raw):
    merged = {"theme": "light", "page_size": 50, "show_sidebar": False}
    merged.update({k: v for k, v in parse_settings(raw).items() if k in merged})
    return merged


if __name__ == "__main__":
    print(merge_with_defaults(DEFAULT_SETTINGS))
    print(merge_with_defaults("__import__('os').getcwd()"))

#!/usr/bin/env python3
"""FP-06: MD5 used as a non-cryptographic content checksum."""
import hashlib


def checksum_bytes(payload):
    """Integrity only: no secret, no attacker-controlled collision target."""
    return hashlib.md5(payload).hexdigest()


def checksum_file(path, chunk_size=65536):
    digest = hashlib.md5()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(chunk_size), b""):
            digest.update(chunk)
    return digest.hexdigest()


def manifest(paths):
    return {p: checksum_file(p) for p in paths}


if __name__ == "__main__":
    print(checksum_bytes(b"release-artifact"))

#!/usr/bin/env python3
"""FP-07: pickle.load of a locally produced, trusted cache file."""
import os
import pickle

CACHE_PATH = os.path.expanduser("~/.cache/metrics.pkl")


def load_cache():
    """The file is written by this same process, so unpickling is acceptable."""
    if not os.path.exists(CACHE_PATH):
        return {}
    with open(CACHE_PATH, "rb") as handle:
        return pickle.load(handle)


def save_cache(data):
    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)
    with open(CACHE_PATH, "wb") as handle:
        pickle.dump(data, handle, protocol=pickle.HIGHEST_PROTOCOL)


def record(metric, value):
    data = load_cache()
    data.setdefault("samples", []).append({"metric": metric, "value": value})
    save_cache(data)
    return len(data["samples"])


if __name__ == "__main__":
    print(record("latency_ms", 42))

#!/usr/bin/env python3
"""FP-08: `random` used for simulation and sampling, not for secrets."""
import random

POPULATION = [f"node-{i:02d}" for i in range(50)]


def sample_servers(k=5, seed=None):
    """Reproducibility matters more than unpredictability here."""
    rng = random.Random(seed)
    return rng.sample(POPULATION, min(k, len(POPULATION)))


def jittered_delay(base_ms=100, spread_ms=25):
    return base_ms + random.uniform(-spread_ms, spread_ms)


def simulate_latency(n=10, seed=7):
    rng = random.Random(seed)
    return [round(rng.gauss(120, 15), 2) for _ in range(n)]


if __name__ == "__main__":
    print(sample_servers(seed=1))
    print(simulate_latency())

#!/usr/bin/env python3
"""FP-09: YAML parsed with safe_load instead of the unsafe full loader."""
from pathlib import Path

import yaml

DEFAULT_WORKFLOW = """
name: nightly
steps:
  - lint
  - test
"""


def parse_workflow(text):
    """safe_load never instantiates arbitrary Python objects."""
    data = yaml.safe_load(text)
    if not isinstance(data, dict):
        return {}
    data.setdefault("steps", [])
    return data


def load_workflow(path):
    return parse_workflow(Path(path).read_text(encoding="utf-8"))


if __name__ == "__main__":
    print(parse_workflow(DEFAULT_WORKFLOW))

#!/usr/bin/env python3
"""FP-10: `assert` used only for internal invariants, not user validation."""
from dataclasses import dataclass


@dataclass
class Money:
    minor_units: int
    currency: str = "USD"

    def add(self, other):
        # Both operands are constructed by callers inside this package,
        # so `assert` is fine even under `python -O` for the demo binary.
        assert self.currency == other.currency
        return Money(self.minor_units + other.minor_units, self.currency)

    def scaled(self, factor):
        return Money(round(self.minor_units * factor), self.currency)

    def __str__(self):
        return f"{self.minor_units / 100:.2f} {self.currency}"


def total(items):
    acc = Money(0)
    for item in items:
        acc = acc.add(item)
    return acc


if __name__ == "__main__":
    print(total([Money(1250), Money(500)]))

#!/usr/bin/env python3
"""FP-11: `eval` replaced by a small, locked-down expression evaluator."""
import operator
import re

_OPS = {
    "+": operator.add,
    "-": operator.sub,
    "*": operator.mul,
    "/": operator.truediv,
}
_TOKEN = re.compile(r"\s*(\d+(?:\.\d+)?|[-+*/])\s*")


def tokenize(expression):
    tokens = []
    pos = 0
    while pos < len(expression):
        match = _TOKEN.match(expression, pos)
        if not match:
            raise ValueError(f"bad token at {pos}: {expression[pos:pos + 8]!r}")
        tokens.append(match.group(1))
        pos = match.end()
    return tokens


def evaluate(expression):
    """Single-pass left-to-right arithmetic; far safer than eval()."""
    tokens = tokenize(expression)
    if not tokens:
        raise ValueError("empty expression")
    value = float(tokens[0])
    for i in range(1, len(tokens) - 1, 2):
        op, operand = tokens[i], float(tokens[i + 1])
        value = _OPS[op](value, operand)
    return value


if __name__ == "__main__":
    print(evaluate("2 + 3 * 4 - 5"))

#!/usr/bin/env python3
"""FP-12: tempfile use without a manual cleanup dance, and no predictable names."""
import json
import os
import tempfile


def dump_report(report):
    """NamedTemporaryFile creates the file with O_EXCL and 0600 permissions."""
    with tempfile.NamedTemporaryFile(
        mode="w", suffix=".json", prefix="report_", delete=False, encoding="utf-8"
    ) as handle:
        json.dump(report, handle)
        return handle.name


def read_back(path):
    with open(path, "r", encoding="utf-8") as handle:
        return json.load(handle)


def build_report(rows):
    tmp_root = tempfile.mkdtemp(prefix="reports_")
    path = os.path.join(tmp_root, "summary.json")
    with open(path, "w", encoding="utf-8") as handle:
        json.dump({"rows": len(rows)}, handle)
    return path


if __name__ == "__main__":
    print(read_back(dump_report({"rows": 3})))

#!/usr/bin/env python3
"""FP-13: broad `except Exception`, but the exception is logged and handled."""
import logging

log = logging.getLogger(__name__)


class UpstreamUnavailable(RuntimeError):
    """Raised when all retries against the upstream provider fail."""


def fetch_profile(client, user_id, retries=3):
    last_error = None
    for attempt in range(1, retries + 1):
        try:
            return client.get(f"/users/{user_id}")
        except Exception as exc:  # transport errors of many shapes
            last_error = exc
            log.warning("profile fetch failed (attempt %d/%d): %s", attempt, retries, exc)
    raise UpstreamUnavailable(f"could not fetch profile for {user_id}") from last_error


def safe_len(value):
    try:
        return len(value)
    except Exception:
        return 0


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    print(safe_len(None), safe_len([1, 2]))

#!/usr/bin/env python3
"""FP-14: file paths built with pathlib plus an explicit containment check."""
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent / "uploads"


def _contained(candidate):
    try:
        candidate.resolve().relative_to(BASE_DIR.resolve())
        return True
    except ValueError:
        return False


def read_upload(name):
    """`..` traversal is rejected after resolution, not by string cleaning."""
    target = BASE_DIR / name
    if not _contained(target):
        raise ValueError(f"path escapes upload dir: {name}")
    return target.read_text(encoding="utf-8")


def write_upload(name, content):
    target = BASE_DIR / name
    if not _contained(target):
        raise ValueError(f"path escapes upload dir: {name}")
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8")
    return target


if __name__ == "__main__":
    print(_contained(BASE_DIR / "../etc/passwd"))

#!/usr/bin/env python3
"""FP-15: requests call without TLS verification being disabled."""
import json

import requests

TIMEOUT = (3.05, 10)


def get_status(url):
    """verify=True is the default, but it is stated explicitly for reviewers."""
    response = requests.get(url, timeout=TIMEOUT, verify=True)
    response.raise_for_status()
    return response.status_code


def post_event(url, payload, token=None):
    headers = {"Content-Type": "application/json"}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    response = requests.post(
        url,
        data=json.dumps(payload),
        headers=headers,
        timeout=TIMEOUT,
        verify=True,
    )
    response.raise_for_status()
    return response.json()


if __name__ == "__main__":
    print(get_status("https://example.com"))

#!/usr/bin/env python3
"""FP-17: regex compiled once at import, and a literal-string swap."""
import re

_HEADER = re.compile(r"^[A-Za-z0-9-]{1,64}$")
_TOKEN = re.compile(r"[A-Za-z0-9._~-]{8,256}\Z")

REDACTIONS = (
    ("Bearer ", "Bearer [redacted]"),
    ("Basic ", "Basic [redacted]"),
)


def valid_header_name(name):
    return bool(_HEADER.fullmatch(name))


def valid_token_shape(token):
    """Shape check only; signature verification happens downstream."""
    return bool(_TOKEN.fullmatch(token))


def redact_authorization(value):
    for prefix, replacement in REDACTIONS:
        if value.startswith(prefix):
            return replacement
    return value


if __name__ == "__main__":
    print(valid_header_name("X-Request-Id"), valid_token_shape("abc123DEF456"))

#!/usr/bin/env python3
"""FP-18: os.path.join plus a fixed suffix, no shell and no interpolation sink."""
import os

DATA_ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data")
ALLOWED_EXTENSIONS = {".csv", ".tsv", ".jsonl"}


def dataset_path(name):
    """Extension allow-list, then a join; the result is only read, never executed."""
    extension = os.path.splitext(name)[1].lower()
    if extension not in ALLOWED_EXTENSIONS:
        raise ValueError(f"unsupported dataset extension: {extension!r}")
    path = os.path.join(DATA_ROOT, name)
    if not os.path.abspath(path).startswith(DATA_ROOT + os.sep):
        raise ValueError(f"dataset escapes data root: {name}")
    return path


def list_datasets():
    if not os.path.isdir(DATA_ROOT):
        return []
    return sorted(
        entry
        for entry in os.listdir(DATA_ROOT)
        if os.path.splitext(entry)[1].lower() in ALLOWED_EXTENSIONS
    )


if __name__ == "__main__":
    print(list_datasets())

#!/usr/bin/env python3
"""FP-19: logging an interpolated password, but only a TLS-protected service token."""
import logging

log = logging.getLogger("auth")

# Values below are public identifiers, not secret material.
ISSUER = "https://auth.example.com"
AUDIENCE = "inventory-api"


def describe_token_claims(claims):
    """Logs `sub` and `scopes` only: the raw token never reaches the log."""
    subject = claims.get("sub", "unknown")
    scopes = claims.get("scope", "").split()
    log.info("token accepted for subject=%s scopes=%s (aud=%s)", subject, scopes, AUDIENCE)
    return {"subject": subject, "scopes": scopes, "issuer": ISSUER}


def is_expired(claims, now):
    return int(claims.get("exp", 0)) <= int(now)


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    print(describe_token_claims({"sub": "svc-1", "scope": "read write", "exp": 0}))

#!/usr/bin/env python3
"""FP-20: JSON deserialized from a response and validated before attribute access."""
import json


class SchemaError(ValueError):
    """Raised when the payload does not match the expected contract."""


def _require(mapping, key, types, default=None):
    if key not in mapping:
        if default is not None:
            return default
        raise SchemaError(f"missing required key: {key}")
    value = mapping[key]
    if not isinstance(value, types):
        raise SchemaError(f"key {key!r} has type {type(value).__name__}")
    return value


def parse_invoice(raw):
    """Structure is checked explicitly; no eval, no attribute guessing."""
    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise SchemaError(f"invalid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise SchemaError("payload must be a JSON object")

    invoice_id = _require(data, "id", str)
    lines = _require(data, "lines", list, default=[])
    clean_lines = []
    for line in lines:
        if not isinstance(line, dict):
            raise SchemaError("each line must be an object")
        clean_lines.append(
            {
                "description": _require(line, "description", str),
                "amount": _require(line, "amount", (int, float)),
            }
        )
    return {"id": invoice_id, "lines": clean_lines}


if __name__ == "__main__":
    print(parse_invoice('{"id": "INV-1", "lines": [{"description": "hosting", "amount": 12.5}]}'))

